using System.Diagnostics;using System.IO;using System.Windows;using SiamNetworkMonitor.Services;
namespace SiamNetworkMonitor;
public partial class SettingsWindow:System.Windows.Window
{
 readonly AppSettingsService _service;readonly AppSettings _settings;readonly MeterSettingsService _meterService=new();SharedMeterSettings _meter;
 static string DataFolder=>Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"SiamNetworkMonitor");
 public SettingsWindow(AppSettingsService service){InitializeComponent();_service=service;_settings=service.Load();_meter=_meterService.Load();StartWindowsBox.IsChecked=service.IsStartupEnabled();StartMinimizedBox.IsChecked=_settings.StartMinimized;NotificationsBox.IsChecked=_settings.NotificationsEnabled;HideFullscreenBox.IsChecked=_settings.HideMeterInFullscreen;MeterWidthBox.Text=_meter.Width.ToString("0");SelectByTag(MeterLayoutBox,_meter.Layout??"Wide");SelectByTag(RetentionBox,_settings.HistoryRetentionDays.ToString());}
 static void SelectByTag(System.Windows.Controls.ComboBox box,string value){foreach(System.Windows.Controls.ComboBoxItem i in box.Items)if(i.Tag?.ToString()==value){box.SelectedItem=i;return;}if(box.Items.Count>0)box.SelectedIndex=0;}
 void Save_Click(object s,RoutedEventArgs e){if(!double.TryParse(MeterWidthBox.Text,out double width)||width<190||width>600){ValidationText.Text="Meter width must be 190–600.";return;}_settings.StartWithWindows=StartWindowsBox.IsChecked==true;_settings.StartMinimized=StartMinimizedBox.IsChecked==true;_settings.NotificationsEnabled=NotificationsBox.IsChecked==true;_settings.HideMeterInFullscreen=HideFullscreenBox.IsChecked==true;_settings.HistoryRetentionDays=RetentionBox.SelectedItem is System.Windows.Controls.ComboBoxItem r&&int.TryParse(r.Tag?.ToString(),out int days)?days:90;_service.Save(_settings);_meter.Width=width;_meter.Layout=(MeterLayoutBox.SelectedItem as System.Windows.Controls.ComboBoxItem)?.Tag?.ToString()??"Wide";_meterService.Save(_meter);DialogResult=true;Close();}
 void Cancel_Click(object s,RoutedEventArgs e){DialogResult=false;Close();}
 void ResetMeter_Click(object s,RoutedEventArgs e){_meterService.Reset();MeterWidthBox.Text="258";SelectByTag(MeterLayoutBox,"Wide");ValidationText.Text="Meter reset will apply after restart.";}
 void OpenDataFolder_Click(object s,RoutedEventArgs e){Directory.CreateDirectory(DataFolder);Process.Start(new ProcessStartInfo("explorer.exe",DataFolder){UseShellExecute=true});}
 void ExportAllHistory_Click(object s,RoutedEventArgs e){var d=new Microsoft.Win32.SaveFileDialog{Filter="CSV file (*.csv)|*.csv",FileName=$"SiamNetworkMonitor-All-History-{DateTime.Now:yyyyMMdd}.csv"};if(d.ShowDialog(this)==true){using var h=new UsageHistoryService();h.ExportCsv(d.FileName,DateTime.MinValue);ValidationText.Text="History exported.";}}
 void ClearUsageHistory_Click(object s,RoutedEventArgs e)=>DeleteWithConfirm("usage-history.json","Clear all usage history? This cannot be undone.");
 void ClearAlertHistory_Click(object s,RoutedEventArgs e)=>DeleteWithConfirm("alert-history.json","Clear all alert history? This cannot be undone.");
 void DeleteWithConfirm(string file,string text){if(System.Windows.MessageBox.Show(this,text,"Confirm",System.Windows.MessageBoxButton.YesNo,System.Windows.MessageBoxImage.Warning,System.Windows.MessageBoxResult.No)!=System.Windows.MessageBoxResult.Yes)return;try{string p=Path.Combine(DataFolder,file);if(File.Exists(p))File.Delete(p);ValidationText.Text=$"{file} cleared. Restart the app.";}catch(Exception ex){ValidationText.Text=ex.Message;}}
}
